# Split into two tests:
@pytest.mark.asyncio
async def test_login_user_wrong_password(client: AsyncClient):
    """Test login with wrong password."""
    await client.post(
        "/api/v1/auth/register",
        json={"email": "badlogin@example.com", "password": "password123"}
    )
    response = await client.post(
        "/api/v1/auth/login",
        json={"email": "badlogin@example.com", "password": "wrongpassword"}
    )
    assert response.status_code == 401
    assert response.json()["detail"] == "Could not validate credentials"

@pytest.mark.asyncio
async def test_login_user_nonexistent_email(client: AsyncClient):
    """Test login with non-existent email."""
    response = await client.post(
        "/api/v1/auth/login",
        json={"email": "nonexistent@example.com", "password": "password123"}
    )
    assert response.status_code == 401
    assert response.json()["detail"] == "Could not validate credentials"

