import React from 'react';
import { render, screen, waitFor, fireEvent } from '@testing-library/react';
import HomePage from './HomePage';
import * as todoApi from '../api/todos';
import { Todo } from '../types/todo';

// Mock the API calls
jest.mock('../api/todos', () => ({
  getTodos: jest.fn(),
  createTodo: jest.fn(),
  toggleTodoComplete: jest.fn(),
  deleteTodo: jest.fn(),
}));

const mockTodos: Todo[] = [
  { id: '1', title: 'Learn React', completed: false },
  { id: '2', title: 'Build a Todo App', completed: true },
];

describe('HomePage', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    (todoApi.getTodos as jest.Mock).mockResolvedValue(mockTodos);
    (todoApi.createTodo as jest.Mock).mockImplementation((title: string) =>
      Promise.resolve({ id: Date.now().toString(), title, completed: false })
    );
    (todoApi.toggleTodoComplete as jest.Mock).mockImplementation((id: string, completed: boolean) =>
      Promise.resolve({ id, title: `Todo ${id}`, completed })
    );
    (todoApi.deleteTodo as jest.Mock).mockResolvedValue(undefined);
  });

  test('renders loading state initially', () => {
    (todoApi.getTodos as jest.Mock).mockReturnValueOnce(new Promise(() => {})); // Never resolve
    render(<HomePage />);
    expect(screen.getByText('Loading todos...')).toBeInTheDocument();
  });

  test('renders todos after fetching', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());
    expect(screen.getByText('Build a Todo App')).toBeInTheDocument();
    expect(screen.getAllByRole('checkbox')).toHaveLength(2);
  });

  test('handles error when fetching todos', async () => {
    (todoApi.getTodos as jest.Mock).mockRejectedValueOnce(new Error('Network error'));
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText(/Error: Failed to fetch todos/i)).toBeInTheDocument());
  });

  test('adds a new todo', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const inputElement = screen.getByPlaceholderText('Add a new todo');
    const addButton = screen.getByRole('button', { name: /add todo/i });

    fireEvent.change(inputElement, { target: { value: 'New Todo Item' } });
    fireEvent.click(addButton);

    await waitFor(() => expect(todoApi.createTodo).toHaveBeenCalledWith('New Todo Item'));
    await waitFor(() => expect(screen.getByText('New Todo Item')).toBeInTheDocument());
  });

  test('toggles todo completion', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const learnReactCheckbox = screen.getAllByRole('checkbox')[0]; // 'Learn React' is the first todo
    expect(learnReactCheckbox).not.toBeChecked();

    fireEvent.click(learnReactCheckbox);

    await waitFor(() => expect(todoApi.toggleTodoComplete).toHaveBeenCalledWith('1', true));
    await waitFor(() => expect(learnReactCheckbox).toBeChecked());
  });

  test('deletes a todo', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const deleteButtons = screen.getAllByRole('button', { name: /delete/i });
    fireEvent.click(deleteButtons[0]); // Delete 'Learn React'

    await waitFor(() => expect(todoApi.deleteTodo).toHaveBeenCalledWith('1'));
    await waitFor(() => expect(screen.queryByText('Learn React')).not.toBeInTheDocument());
    expect(screen.getByText('Build a Todo App')).toBeInTheDocument();
  });
});

using Microsoft.EntityFrameworkCore;
using Api.Data;
using Api.Models;
using Api.DTOs;
using Api.Services;
using Api.Results;
using Microsoft.AspNetCore.Diagnostics; // Added for IExceptionHandlerPathFeature
using Microsoft.AspNetCore.Authentication.JwtBearer; // Added for JWT
using Microsoft.AspNetCore.Authorization; // Added for Authorize attribute
using Microsoft.IdentityModel.Tokens; // Added for SymmetricSecurityKey
using System.Text; // Added for Encoding

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

// Configure logging
builder.Services.AddLogging(config =>
{
    config.AddConsole();
    config.AddDebug();
});

// Configure PostgreSQL DbContext
builder.Services.AddDbContextFactory<AppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection")));

// Register TodoService
builder.Services.AddScoped<ITodoService, TodoService>();

// Configure JWT Authentication
var jwtSecret = builder.Configuration["Jwt:Key"] ?? throw new InvalidOperationException("JWT Secret Key not configured.");
builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = true,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
        ValidIssuer = builder.Configuration["Jwt:Issuer"],
        ValidAudience = builder.Configuration["Jwt:Audience"],
        IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtSecret))
    };
});
builder.Services.AddAuthorization();


var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

// Global exception handler (F-001 fix)
app.UseExceptionHandler(exceptionHandlerApp =>
{
    exceptionHandlerApp.Run(async context =>
    {
        var exceptionHandlerPathFeature = context.Features.Get<IExceptionHandlerPathFeature>();
        var exception = exceptionHandlerPathFeature?.Error;

        // Log the exception details
        var logger = context.RequestServices.GetRequiredService<ILogger<Program>>();
        logger.LogError(exception, "An unhandled exception occurred: {Message}", exception?.Message);

        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
        await context.Response.WriteAsync("An unexpected error occurred.");
    });
});

// Add Authentication and Authorization middleware (F-002 fix)
app.UseAuthentication();
app.UseAuthorization();

// API Endpoints
app.MapGet("/v1/todos", [Authorize] async (ITodoService todoService) => // F-002 fix
{
    var result = await todoService.GetAllTodos();
    return Results.Ok(result.Value);
})
.WithName("GetAllTodos")
.Produces<IEnumerable<TodoResponse>>(StatusCodes.Status200OK);

app.MapPost("/v1/todos", [Authorize] async (CreateTodoRequest request, ITodoService todoService) => // F-002 fix
{
    var result = await todoService.CreateTodo(request);
    if (result.IsSuccess)
    {
        return Results.CreatedAtRoute("GetAllTodos", new { id = result.Value.Id }, result.Value);
    }
    return Results.BadRequest(result.Error);
})
.WithName("CreateTodo")
.Produces<TodoResponse>(StatusCodes.Status201Created); // F-005 fix: Removed .Produces(StatusCodes.Status400BadRequest)

app.MapPut("/v1/todos/{id}/complete", [Authorize] async (Guid id, ITodoService todoService) => // F-002 fix
{
    var result = await todoService.CompleteTodo(id);
    if (result.IsSuccess)
    {
        return Results.Ok(result.Value);
    }
    return Results.NotFound(result.Error);
})
.WithName("CompleteTodo")
.Produces<TodoResponse>(StatusCodes.Status200OK); // F-005 fix: Removed .Produces(StatusCodes.Status404NotFound)

app.MapDelete("/v1/todos/{id}", [Authorize] async (Guid id, ITodoService todoService) => // F-002 fix
{
    var result = await todoService.DeleteTodo(id);
    if (result.IsSuccess)
    {
        return Results.NoContent();
    }
    return Results.NotFound(result.Error);
})
.WithName("DeleteTodo")
.Produces(StatusCodes.Status204NoContent); // F-005 fix: Removed .Produces(StatusCodes.Status404NotFound)

app.Run();

