import React, { createContext, useState, useEffect, ReactNode } from 'react';
import { AuthResponse, User } from '../types';
import { login as apiLogin, register as apiRegister } from '../services/auth';

interface AuthContextType {
  isAuthenticated: boolean;
  user: User | null;
  token: string | null;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string) => Promise<void>;
  logout: () => void;
  loading: boolean;
  error: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const storedToken = localStorage.getItem('jwt_token');
    if (storedToken) {
      setToken(storedToken);
      setIsAuthenticated(true);
      // In a real app, you'd decode the token or make an API call to get user info
      // For simplicity, we'll just set a dummy user for now if token exists
      setUser({ id: 'dummy-id', email: 'user@example.com' });
    }
    setLoading(false);
  }, []);

  const handleAuthSuccess = (authResponse: AuthResponse, email: string) => {
    localStorage.setItem('jwt_token', authResponse.access_token);
    setToken(authResponse.access_token);
    setIsAuthenticated(true);
    setUser({ id: 'some-id', email: email }); // Placeholder user
    setError(null);
  };

  const login = async (email: string, password: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiLogin({ email, password });
      handleAuthSuccess(response.data, email);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Login failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const register = async (email: string, password: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiRegister({ email, password });
      handleAuthSuccess(response.data, email);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Registration failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('jwt_token');
    setToken(null);
    setIsAuthenticated(false);
    setUser(null);
    setError(null);
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, user, token, login, register, logout, loading, error }}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext;

using Microsoft.EntityFrameworkCore;
using Api.Data;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Authorization; // Added for authorization

namespace Api.Features.Todos;

/// <summary>
/// Provides extension methods to map Todo-related API endpoints.
/// </summary>
public static class TodoEndpoints
{
    public static IEndpointRouteBuilder MapTodoEndpoints(this IEndpointRouteBuilder app)
    {
        var todosApi = app.MapGroup("/api/v1/todos")
            .WithTags("Todos")
            .RequireAuthorization(); // Example: Requires authentication for all endpoints in this group

        // Further authorization logic would be needed within endpoints, e.g., checking UserId

        // GET /api/v1/todos
        todosApi.MapGet("/", async (
            IDbContextFactory<AppDbContext> dbContextFactory,
            bool? completed = null) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var query = dbContext.Todos.AsQueryable();

            if (completed.HasValue)
            {
                query = query.Where(t => t.Completed == completed.Value);
            }

            var todos = await query
                .OrderBy(t => t.CreatedAt)
