from datetime import datetime, timedelta, timezone
from typing import Optional
from passlib.context import CryptContext
from jose import JWTError, jwt

from src.config import settings
from src.schemas.auth import TokenData
from src.exceptions import InvalidCredentialsException

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Verify a plain password against a hashed password."""
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    """Hash a password."""
    return pwd_context.hash(password)

def create_access_token(data: dict, expires_delta: Optional[timedelta] = None) -> str:
    """Create a JWT access token."""
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.now(timezone.utc) + expires_delta
    else:
        expire = datetime.now(timezone.utc) + timedelta(minutes=settings.access_token_expire_minutes)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, settings.secret_key, algorithm=settings.algorithm)
    return encoded_jwt

def decode_access_token(token: str) -> TokenData:
    """Decode and validate a JWT access token."""
    try:
        payload = jwt.decode(token, settings.secret_key, algorithms=[settings.algorithm])
        user_id: str = payload.get("sub")
        if user_id is None:
            raise InvalidCredentialsException()
        token_data = TokenData(user_id=user_id)
    except JWTError:
        raise InvalidCredentialsException()
    return token_data

import { useAuth } from '../context/AuthContext';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8000/v1'; // Use environment variable or fallback

interface RequestOptions extends RequestInit {
  isAuthRequired?: boolean;
}

export const apiRequest = async <T>(endpoint: string, options: RequestOptions = {}): Promise<T> => {
  const { isAuthRequired = true, headers, ...restOptions } = options;
  const token = localStorage.getItem('accessToken'); // Directly access token for utility function

  const config: RequestInit = {
    ...restOptions,
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
  };

  if (isAuthRequired) {
    if (!token) {
      // Handle unauthenticated state, e.g., redirect to login
      // In a real app, you might want to use a global error handler or a specific hook
      console.error('Authentication required, no token found.');
      throw new Error('Unauthorized');
    }
    config.headers = {
      ...config.headers,
      'Authorization': `Bearer ${token}`,
    };
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, config);

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ message: response.statusText }));
    throw new Error(errorData.message || 'Something went wrong');
  }

  // Handle cases where response might be empty (e.g., DELETE requests)
  if (response.status === 204) {
    return {} as T; // Return an empty object for no content responses
  }

  return response.json();
};

// Define common API functions
export const authApi = {
  register: (data: any) => apiRequest('/auth/register', { method: 'POST', body: JSON.stringify(data), isAuthRequired: false }),
  login: (data: any) => apiRequest<{ access_token: string, token_type: string }>('/auth/login', { method: 'POST', body: JSON.stringify(data), isAuthRequired: false }),
};

export const todosApi = {
  getAll: () => apiRequest<Todo[]>('/todos', { method: 'GET' }),
  getById: (id: number) => apiRequest<Todo>(`/todos/${id}`, { method: 'GET' }),
  create: (data: { title: string; description: string; completed?: boolean }) => apiRequest<Todo>('/todos', { method: 'POST', body: JSON.stringify(data) }),
  update: (id: number, data: { title?: string; description?: string; completed?: boolean }) => apiRequest<Todo>(`/todos/${id}`, { method: 'PUT', body: JSON.stringify(data) }),
  delete: (id: number) => apiRequest<{ message: string }>(`/todos/${id}`, { method: 'DELETE' }),
};

// Basic Todo type definition
export interface Todo {
  id: number;
  title: string;
  description: string;
  completed: boolean;
  created_at: string;
  updated_at: string;
}

