using Api.Models.Auth;
using FluentAssertions;
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Xunit;
using Api; // Assuming Program is in Api namespace

namespace IntegrationTests
{
    public class AuthEndpointsIntegrationTests : IClassFixture<CustomWebApplicationFactory<Program>>
    {
        private readonly HttpClient _client;

        public AuthEndpointsIntegrationTests(CustomWebApplicationFactory<Program> factory)
        {
            _client = factory.CreateClient();
        }

        [Fact]
        public async Task Register_ShouldReturnOk_WhenValidRequest()
        {
            // Arrange
            var request = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/register", request);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.OK);
            var authTokens = await response.Content.ReadFromJsonAsync<AuthTokens>();
            authTokens.Should().NotBeNull();
            authTokens!.AccessToken.Should().NotBeNullOrEmpty();
        }

        [Fact]
        public async Task Register_ShouldReturnBadRequest_WhenEmailAlreadyExists()
        {
            // Arrange
            // Register once
            var initialRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", initialRequest);

            // Attempt to register again with the same email
            var duplicateRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/register", duplicateRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.BadRequest);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Email already registered");
        }

        [Fact]
        public async Task Login_ShouldReturnOk_WhenValidCredentials()
        {
            // Arrange
            // Register a user first
            var registerRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.OK);
            var authTokens = await response.Content.ReadFromJsonAsync<AuthTokens>();
            authTokens.Should().NotBeNull();
            authTokens!.AccessToken.Should().NotBeNullOrEmpty();
        }

        [Fact]
        public async Task Login_ShouldReturnUnauthorized_WhenInvalidCredentials()
        {
            // Arrange
            // Register a user first
            var registerRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest(TestConstants.TestUserEmail, "WrongPassword123!");

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.Unauthorized);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Invalid credentials");
        }

        [Fact]
        public async Task Login_ShouldReturnUnauthorized_WhenUserDoesNotExist()
        {
            // Arrange
            var loginRequest = new LoginRequest("nonexistent@example.com", "Password123!");

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.Unauthorized);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Invalid credentials");
        }
    }
}

