import React, { useEffect, useState, useCallback } from 'react';
import AddTodoForm from '../components/AddTodoForm';
import TodoList from '../components/TodoList';
import { Todo } from '../types/todo';
import { getTodos, createTodo, completeTodo } from '../api/todos';
import './HomePage.css';

const HomePage: React.FC = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    try {
      setLoading(true);
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while fetching todos.');
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const handleAddTodo = async (title: string) => {
    try {
      const newTodo = await createTodo(title);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while adding a todo.');
      }
    }
  };

  const handleToggleComplete = async (id: string) => {
    try {
      const updatedTodo = await completeTodo(id);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updatedTodo : todo))
      );
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while completing a todo.');
      }
    }
  };

  if (loading) {
    return <div className="homepage-container">Loading todos...</div>;
  }

  if (error) {
    console.error("Detailed error:", error); // Log the actual error for debugging
    return <div className="homepage-container error-message">An unexpected error occurred. Please try again later.</div>;
  }

  return (
    <div className="homepage-container">
      <h1>My Todo List</h1>
      <AddTodoForm onAddTodo={handleAddTodo} />
      <TodoList todos={todos} onToggleComplete={handleToggleComplete} />
    </div>
  );
};

export default HomePage;

using Microsoft.EntityFrameworkCore;
using Api.Data;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Api.Features.Todos;

/// <summary>
/// Provides extension methods to map Todo-related API endpoints.
/// </summary>
public static class TodoEndpoints
{
    public static IEndpointRouteBuilder MapTodoEndpoints(this IEndpointRouteBuilder app)
    {
        var todosApi = app.MapGroup("/api/v1/todos")
            .WithTags("Todos");

        // GET /api/v1/todos
        todosApi.MapGet("/", async (
            IDbContextFactory<AppDbContext> dbContextFactory,
            bool? completed = null) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var query = dbContext.Todos.AsQueryable();

            if (completed.HasValue)
            {
                query = query.Where(t => t.Completed == completed.Value);
            }

            var todos = await query
                .OrderBy(t => t.CreatedAt)
                .Select(t => new TodoResponse(t.Id, t.Title, t.Description, t.Completed, t.CreatedAt, t.UpdatedAt))
                .ToListAsync();

            return TypedResults.Ok(todos);
        })
        .WithName("GetAllTodos")
        .WithOpenApi();

        // GET /api/v1/todos/{id}
        todosApi.MapGet("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            return todo is null
                ? TypedResults.NotFound()
                : TypedResults.Ok(new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt));
        })
        .WithName("GetTodoById")
        .WithOpenApi();

        // POST /api/v1/todos
        todosApi.MapPost("/", async (CreateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var now = DateTimeOffset.UtcNow;
            var todo = new Todo
            {
                Id = Guid.NewGuid(),
                Title = request.Title,
                Description = request.Description,
                Completed = request.Completed,
                CreatedAt = now,
                UpdatedAt = now
            };

            dbContext.Todos.Add(todo);
            await dbContext.SaveChangesAsync();

            var todoResponse = new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt);
            return TypedResults.CreatedAtRoute(todoResponse, "GetTodoById", new { id = todo.Id });
        })
        .WithName("CreateTodo")
        .WithOpenApi();

        // PUT /api/v1/todos/{id}
        todosApi.MapPut("/{id:guid}", async (Guid id, UpdateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            todo.Title = request.Title ?? todo.Title;
            todo.Description = request.Description ?? todo.Description;
            todo.Completed = request.Completed ?? todo.Completed;
            todo.UpdatedAt = DateTimeOffset.UtcNow;

            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("UpdateTodo")
        .WithOpenApi();

        // DELETE /api/v1/todos/{id}
        todosApi.MapDelete("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            dbContext.Todos.Remove(todo);
            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("DeleteTodo")
        .WithOpenApi();

        return app;
    }
}

