import {
  Repository,
  Commit,
  PullRequest,
  Issue,
  AddRepoRequest,
  AddRepoResponse,
  SyncResponse,
} from '../types/api';

const BASE_URL = '/api/v1'; // Assuming proxy or direct access

interface ApiOptions extends RequestInit {
  apiKey?: string;
}

async function fetchApi<T>(
  path: string,
  options?: ApiOptions
): Promise<T> {
  const headers = {
    'Content-Type': 'application/json',
    ...options?.headers,
  };

  // Add API key if provided (for simple personal use)
  if (options?.apiKey) {
    headers['X-API-Key'] = options.apiKey;
  }

  const response = await fetch(`${BASE_URL}${path}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ message: 'Unknown error' }));
    throw new Error(errorData.message || `API Error: ${response.statusText}`);
  }

  return response.json();
}

export const apiClient = {
  getRepos: (): Promise<Repository[]> => {
    return fetchApi<Repository[]>('/repos');
  },

  addRepo: (data: AddRepoRequest): Promise<AddRepoResponse> => {
    return fetchApi<AddRepoResponse>('/repos', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  getRepoDetail: (repoId: string): Promise<Repository> => {
    return fetchApi<Repository>(`/repos/${repoId}`);
  },

  deleteRepo: (repoId: string): Promise<{ message: string }> => {
    return fetchApi<{ message: string }>(`/repos/${repoId}`, {
      method: 'DELETE',
    });
  },

  getCommits: (repoId: string): Promise<Commit[]> => {
    return fetchApi<Commit[]>(`/repos/${repoId}/activity/commits`);
  },

  getPulls: (repoId: string): Promise<PullRequest[]> => {
    return fetchApi<PullRequest[]>(`/repos/${repoId}/activity/pulls`);
  },

  getIssues: (repoId: string): Promise<Issue[]> => {
    return fetchApi<Issue[]>(`/repos/${repoId}/activity/issues`);
  },

  triggerSync: (): Promise<SyncResponse> => {
    return fetchApi<SyncResponse>('/sync', {
      method: 'POST',
    });
  },
};

import React from 'react';
import { ActivityEvent, Commit, PullRequest, Issue } from '../types/api';
import './ActivityFeedItem.css';

interface ActivityFeedItemProps {
  event: ActivityEvent;
}

const ActivityFeedItem: React.FC<ActivityFeedItemProps> = ({ event }) => {
  const renderCommit = (commit: Commit) => (
    <>
      <span className="ActivityFeedItem-icon">📝</span>
      <div className="ActivityFeedItem-content">
        <a href={commit.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          Commit: {commit.message.split('\n')[0]}
        </a>
        <p className="ActivityFeedItem-meta">
          by {commit.author} on {new Date(commit.date).toLocaleString()}
        </p>
      </div>
    </>
  );

  const renderPullRequest = (pr: PullRequest) => (
    <>
      <span className="ActivityFeedItem-icon">
        {pr.state === 'open' ? '🔀' : pr.state === 'merged' ? '✅' : '❌'}
      </span>
      <div className="ActivityFeedItem-content">
        <a href={pr.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          PR #{pr.number}: {pr.title} ({pr.state})
        </a>
        <p className="ActivityFeedItem-meta">
          by {pr.author} created on {new Date(pr.createdAt).toLocaleString()}
        </p>
      </div>
    </>
  );

  const renderIssue = (issue: Issue) => (
    <>
      <span className="ActivityFeedItem-icon">
        {issue.state === 'open' ? '❗' : '✔️'}
      </span>
      <div className="ActivityFeedItem-content">
        <a href={issue.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          Issue #{issue.number}: {issue.title} ({issue.state})
        </a>
        <p className="ActivityFeedItem-meta">
          by {issue.author} created on {new Date(issue.createdAt).toLocaleString()}
        </p>
      </div>
    </>
  );

  return (
    <div className="ActivityFeedItem">
      {event.type === 'commit' && renderCommit(event as Commit)}
      {event.type === 'pull_request' && renderPullRequest(event as PullRequest)}
      {event.type === 'issue' && renderIssue(event as Issue)}
    </div>
  );
};

export default ActivityFeedItem;

